CREATE TYPE "CaseStatus" AS ENUM ('gross_pending','gross_done','micro_pending','micro_done','with_consultant','consultant_dx_added','report_draft','report_approved','with_typist','needs_confirmation','delivered');
CREATE TYPE "CasePriority" AS ENUM ('routine','urgent');
CREATE TYPE "StepName" AS ENUM ('gross','micro','consultant','report','typist','delivered');
CREATE TYPE "StepStatus" AS ENUM ('pending','done','skipped','forced');
CREATE TABLE "settings" ("id" INTEGER PRIMARY KEY DEFAULT 1,"pin_hash" TEXT NOT NULL,"failed_attempts" INTEGER NOT NULL DEFAULT 0,"locked_until" TIMESTAMP(3),"ai_provider" TEXT NOT NULL DEFAULT 'groq',"ai_base_url" TEXT,"model_text" TEXT,"model_stt" TEXT,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "batches" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"range_start" TEXT NOT NULL,"range_end" TEXT NOT NULL,"count" INTEGER NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "cases" ("id" SERIAL PRIMARY KEY,"case_label" TEXT NOT NULL UNIQUE,"batch_id" INTEGER,"specimen_type" TEXT,"priority" "CasePriority" NOT NULL DEFAULT 'routine',"status" "CaseStatus" NOT NULL DEFAULT 'gross_pending',"incomplete" BOOLEAN NOT NULL DEFAULT false,"locked" BOOLEAN NOT NULL DEFAULT false,"delivered_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "case_steps" ("id" SERIAL PRIMARY KEY,"case_id" INTEGER NOT NULL,"step" "StepName" NOT NULL,"status" "StepStatus" NOT NULL DEFAULT 'pending',"reason" TEXT,"completed_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL);
CREATE TABLE "events" ("id" SERIAL PRIMARY KEY,"case_id" INTEGER,"type" TEXT NOT NULL,"payload" JSONB,"at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "case_steps_case_id_step_key" ON "case_steps"("case_id","step"); CREATE INDEX "cases_status_idx" ON "cases"("status"); CREATE INDEX "events_case_id_at_idx" ON "events"("case_id","at");
ALTER TABLE "cases" ADD CONSTRAINT "cases_batch_id_fkey" FOREIGN KEY ("batch_id") REFERENCES "batches"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "case_steps" ADD CONSTRAINT "case_steps_case_id_fkey" FOREIGN KEY ("case_id") REFERENCES "cases"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "events" ADD CONSTRAINT "events_case_id_fkey" FOREIGN KEY ("case_id") REFERENCES "cases"("id") ON DELETE CASCADE ON UPDATE CASCADE;
